function lerCadastros(){const a=localStorage.getItem("cadastros");return null===a?[]:JSON.parse(a)}function salvarCadastro(a){const t=lerCadastros();t.push(a),localStorage.setItem("cadastros",JSON.stringify(t))}function limparCadastros(){localStorage.removeItem("cadastros")}function lerTemaEscuro(){return"escuro"===localStorage.getItem("tema")}function salvarTema(a){localStorage.setItem("tema",a?"escuro":"claro")}